/**
 * Opaque object name for a member photo (item interno, 26/10/2026).
 *
 * The bucket `member-photos` is PUBLIC and `members.photo_url` carries the object URL, so the
 * object name is public too. It used to be the member's e-mail with `@` and `.` replaced by `_`.
 * It is now `avatars/<key>.<ext>`, where `<key>` is the member's row in `public.member_photo_keys`:
 * 128 random bits as 32 lowercase hex characters, generated by the database and derived from no
 * personal or public data (not the e-mail, not the name, not the member id, not a hash of them).
 *
 * The key is stable per member, so a new upload overwrites the same object instead of piling up a
 * new one, and the storage write policies can key on it. The extension is the only part that
 * varies, which is why `stalePhotoPaths` exists: after a JPEG replaces a PNG (or the reverse), the
 * other one is an old photo nobody references and is removed.
 *
 * Pure functions, no Deno or Node API: the Edge Function, the migration script and the guards
 * import this one file, so the rule lives in one place.
 */

/** 32 lowercase hex characters = 128 bits. Same shape as the CHECK on member_photo_keys. */
export const PHOTO_KEY_RE = /^[0-9a-f]{32}$/;

/** The only extensions a photo object may carry. The storage policies list exactly these two. */
export const PHOTO_EXTENSIONS = ["jpg", "png"] as const;

/** Object name prefix inside the bucket. */
export const PHOTO_PREFIX = "avatars/";

/** Full shape of an opaque photo object name. */
export const OPAQUE_PHOTO_PATH_RE = /^avatars\/[0-9a-f]{32}\.(jpg|png)$/;

/** Extension for an uploaded photo, by MIME type. Null for anything that is not JPEG or PNG. */
export function photoExtensionFor(mime: string): "jpg" | "png" | null {
  if (mime === "image/jpeg") return "jpg";
  if (mime === "image/png") return "png";
  return null;
}

/** Object name for a member's photo. Throws on a malformed key or an unsupported type. */
export function photoObjectPath(objectKey: string, mime: string): string {
  if (!PHOTO_KEY_RE.test(objectKey)) throw new Error("invalid photo object key");
  const ext = photoExtensionFor(mime);
  if (!ext) throw new Error("unsupported photo type");
  return `${PHOTO_PREFIX}${objectKey}.${ext}`;
}

/** The same key under the other allowed extension(s): what a fresh upload leaves stale. */
export function stalePhotoPaths(path: string): string[] {
  const m = path.match(/^avatars\/([0-9a-f]{32})\.(jpg|png)$/);
  if (!m) throw new Error("not an opaque photo path");
  return PHOTO_EXTENSIONS.filter((e) => e !== m[2]).map((e) => `${PHOTO_PREFIX}${m[1]}.${e}`);
}

/** True when the object name is the opaque shape for THIS key (any allowed extension). */
export function isOwnOpaquePhotoPath(path: string, objectKey: string): boolean {
  const m = path.match(/^avatars\/([0-9a-f]{32})\.(jpg|png)$/);
  return !!m && m[1] === objectKey;
}
